using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- AI client setup ---------------------------------------------------------

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();
var webSearch = new WebSearchTool();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchAsync),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Agent -------------------------------------------------------------------

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. Your job is to research a topic thoroughly by
        searching the web and taking notes on key findings.

        Follow this process:
        1. Break the topic into 2-3 specific search queries.
        2. For each query, call the SearchWeb tool to find information.
        3. After each search, call SaveNote to record the most important findings
           (include the source URL when available).
        4. After completing all searches, call GetNotes to review everything you collected.
        5. Finally, write a well-structured summary with sections, citing your sources.

        Be thorough but concise. Focus on factual, up-to-date information.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

// --- Run ---------------------------------------------------------------------

await foreach (var update in agent.RunStreamingAsync(topic, options: runOptions))
{
    Console.Write(update.Text);
}

Console.WriteLine();

// --- Helpers -----------------------------------------------------------------

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrWhiteSpace(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// =============================================================================
// Tool implementations
// =============================================================================

/// <summary>Simulates web search by fetching and parsing real web pages via DuckDuckGo Lite.</summary>
sealed class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    [Description("Searches the web for the given query and returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> SearchAsync(
        [Description("The search query to look up on the web.")] string query)
    {
        try
        {
            // Use DuckDuckGo Lite (HTML) — no API key required.
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

            var html = await s_http.GetStringAsync(url);

            var results = ParseDuckDuckGoLite(html, maxResults: 5);

            if (results.Count == 0)
            {
                return $"No results found for \"{query}\".";
            }

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for \"{query}\":\n");
            for (var i = 0; i < results.Count; i++)
            {
                var (title, snippet, link) = results[i];
                sb.AppendLine($"{i + 1}. {title}");
                sb.AppendLine($"   URL: {link}");
                sb.AppendLine($"   {snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Url)> ParseDuckDuckGoLite(
        string html, int maxResults)
    {
        var results = new List<(string, string, string)>();

        // DuckDuckGo Lite returns results in a table structure.
        // Each result has an <a> link followed by snippet text in a <td> with class "result-snippet".
        var linkMarker = "class=\"result-link\"";
        var snippetMarker = "class=\"result-snippet\"";
        var pos = 0;

        while (results.Count < maxResults)
        {
            var linkIdx = html.IndexOf(linkMarker, pos, StringComparison.OrdinalIgnoreCase);
            if (linkIdx < 0) break;

            // Extract href
            var hrefStart = html.LastIndexOf("href=\"", linkIdx, Math.Min(linkIdx, 200), StringComparison.OrdinalIgnoreCase);
            var urlValue = "";
            if (hrefStart >= 0)
            {
                hrefStart += 6;
                var hrefEnd = html.IndexOf('"', hrefStart);
                if (hrefEnd > hrefStart)
                    urlValue = WebUtility.HtmlDecode(html[hrefStart..hrefEnd]);
            }

            // Extract title (text inside the <a> tag)
            var tagClose = html.IndexOf('>', linkIdx);
            var titleEnd = tagClose > 0 ? html.IndexOf("</a>", tagClose, StringComparison.OrdinalIgnoreCase) : -1;
            var title = tagClose > 0 && titleEnd > tagClose
                ? StripHtml(html[(tagClose + 1)..titleEnd]).Trim()
                : "(no title)";

            // Extract snippet
            var snippet = "";
            var snippetIdx = html.IndexOf(snippetMarker, linkIdx, StringComparison.OrdinalIgnoreCase);
            if (snippetIdx >= 0)
            {
                var snippetTagClose = html.IndexOf('>', snippetIdx);
                var snippetEnd = snippetTagClose > 0
                    ? html.IndexOf("</td>", snippetTagClose, StringComparison.OrdinalIgnoreCase)
                    : -1;
                if (snippetTagClose > 0 && snippetEnd > snippetTagClose)
                    snippet = StripHtml(html[(snippetTagClose + 1)..snippetEnd]).Trim();
            }

            if (!string.IsNullOrWhiteSpace(title) && !string.IsNullOrWhiteSpace(urlValue))
            {
                results.Add((title, snippet, urlValue));
            }

            pos = linkIdx + linkMarker.Length;
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder(html.Length);
        var inTag = false;
        foreach (var c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) sb.Append(c);
        }
        return WebUtility.HtmlDecode(sb.ToString());
    }
}

/// <summary>A simple in-memory notebook for the agent to save and retrieve research notes.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note. Use this to record important findings from web searches. Include source URLs.")]
    public string SaveNote(
        [Description("The note content to save, including key findings and source URL.")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieves all previously saved research notes so you can review them before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"All research notes ({_notes.Count} total):\n");
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"--- Note #{i + 1} ---");
            sb.AppendLine(_notes[i]);
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

