+/// <summary>A simple in-memory notebook for the agent to save and retrieve research notes.</summary>
+sealed class Notebook
+{
+    private readonly List<string> _notes = [];
+
+    [Description("Saves a research note. Use this to record important findings from web searches. Include source URLs.")]
+    public string SaveNote(
+        [Description("The note content to save, including key findings and source URL.")] string note)
+    {
+        _notes.Add(note);
+        return $"Note #{_notes.Count} saved.";
+    }
+
+    [Description("Retrieves all previously saved research notes so you can review them before writing a summary.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        var sb = new StringBuilder();
+        sb.AppendLine($"All research notes ({_notes.Count} total):\n");
+        for (var i = 0; i < _notes.Count; i++)
+        {
+            sb.AppendLine($"--- Note #{i + 1} ---");
+            sb.AppendLine(_notes[i]);
+            sb.AppendLine();
+        }
+        return sb.ToString();
+    }
+}
